  if (nums.length < 1 || nums.length > 1000) return 'nums needs 1 to 1000 values.';
  if (nums.some(v => !Number.isInteger(v) || v < 1 || v > 10000)) return 'Each value is a whole number from 1 to 10^4.';
  return null;
}

