function findTheArrayConcVal(nums) {
  let left = 0;
  let right = nums.length - 1;
  let total = 0;
  while (left < right) {
    let shift = 1;
    while (shift <= nums[right]) {
      shift *= 10;
    }
    total += nums[left] * shift + nums[right];
    left++;
    right--;
  }
  if (left === right) {
    total += nums[left];
  }
  return total;
}

