function findTheArrayConcVal(nums) {
  // Follow the statement literally: remove elements from the ends and join their digit strings.
  const rest = nums.slice();
  let value = 0;
  while (rest.length > 0) {
    if (rest.length === 1) {
      value += rest.pop();
    } else {
      const first = rest.shift();
      const last = rest.pop();
      value += Number(String(first) + String(last));
    }
  }
  return value;
}

