function generate(rand, size) {
  const special = [1, 9, 10, 99, 100, 999, 1000, 9999, 10000];
  const value = () => {
    const roll = rand();
    if (roll < 0.35) return special[Math.floor(rand() * special.length)];
    if (roll < 0.6) return 1 + Math.floor(rand() * 20);
    return 1 + Math.floor(rand() * 10000);
  };
  if (size === 'small') {
    const n = 1 + Math.floor(rand() * 8);
    return [Array.from({ length: n }, value)];
  }
  const n = rand() < 0.5 ? 1000 : 1 + Math.floor(rand() * 1000);
  if (rand() < 0.25) return [Array.from({ length: n }, () => 10000)];
  return [Array.from({ length: n }, value)];
}
